'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var dormbr = require( './../lib' );

// Define a matrix C stored in column-major order:
var shape = [ 2, 3 ];
var order = 'column-major';
var strides = shape2strides( shape, order );

var C = new Float64Array( [ 1.0, 2.0, 4.0, 5.0, 3.0, 6.0 ] );
console.log( ndarray2array( C, shape, strides, 0, order ) );

// Define the reflector vector A (stored in column-major order, LDA=2) and scalar factors:
var A = new Float64Array( [ 1.0, 0.0, 0.0 ] );
var TAU = new Float64Array( [ 2.0 ] );
var WORK = new Float64Array( 3 );

// Apply the orthogonal matrix Q from the left (no transpose):
var info = dormbr( order, 'Q', 'left', 'no-transpose', shape[ 0 ], shape[ 1 ], 1, A, 2, TAU, C, strides[ 1 ], WORK, WORK.length );
console.log( ndarray2array( C, shape, strides, 0, order ) );
console.log( info );

// Define a matrix C stored in column-major order:
shape = [ 4, 3 ];
strides = shape2strides( shape, order );

C = new Float64Array([
	4.0,
	5.0,
	6.0,
	7.0,
	7.0,
	8.0,
	9.0,
	10.0,
	10.0,
	11.0,
	12.0,
	13.0
]);
console.log( ndarray2array( C, shape, strides, 0, order ) );

// Define the reflector vectors A (stored in column-major order, LDA=4) and scalar factors:
A = new Float64Array([
	1.0,
	0.0,
	0.0,
	-0.125,
	0.5,
	1.0,
	0.0,
	0.25,
	0.25,
	0.5,
	1.0,
	0.5,
	0.0,
	0.0,
	0.0,
	0.0
]);
TAU = new Float64Array( [ 1.5, 0.75, 0.0 ] );
WORK = new Float64Array( 3 );

// Apply the orthogonal matrix P^T from the left (no transpose):
info = dormbr( order, 'P', 'left', 'no-transpose', shape[ 0 ], shape[ 1 ], 3, A, 4, TAU, C, strides[ 1 ], WORK, WORK.length );
console.log( ndarray2array( C, shape, strides, 0, order ) );
console.log( info );
